describe('Form Autocomplete Attributes', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should have correct autocomplete attributes on standard form fields', () => {
    cy.get('input[name="email"]').should('have.attr', 'autocomplete', 'email');
    cy.get('input[name="password"]').should('have.attr', 'autocomplete', 'current-password');
    cy.get('input[name="username"]').should('have.attr', 'autocomplete', 'username');
    cy.get('input[name="phone"]').should('have.attr', 'autocomplete', 'tel');
    cy.get('input[name="address"]').should('have.attr', 'autocomplete', 'street-address');
    cy.get('input[name="city"]').should('have.attr', 'autocomplete', 'address-level2');
    cy.get('input[name="zipcode"]').should('have.attr', 'autocomplete', 'postal-code');
  });

  it('should have autocomplete disabled on sensitive fields', () => {
    cy.get('input[name="creditCard"]').should('have.attr', 'autocomplete', 'off');
    cy.get('input[name="cvv"]').should('have.attr', 'autocomplete', 'off');
    cy.get('input[name="securityQuestion"]').should('have.attr', 'autocomplete', 'off');
  });

  it('should have correct autocomplete attributes on name fields', () => {
    cy.get('input[name="firstName"]').should('have.attr', 'autocomplete', 'given-name');
    cy.get('input[name="lastName"]').should('have.attr', 'autocomplete', 'family-name');
  });

  it('should handle missing autocomplete attributes gracefully', () => {
    cy.get('input[name="optionalField"]').then(($input) => {
      const autocompleteAttr = $input.attr('autocomplete');
      expect(autocompleteAttr).to.be.oneOf([undefined, 'off', 'on']);
    });
  });

  it('should validate autocomplete on form submission with autofilled data', () => {
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();
    cy.get('input[name="email"]').should('have.value', 'test@example.com');
    cy.get('input[name="password"]').should('have.value', 'password123');
  });
});
